<div class="page-actions"><div><p class="text-muted mb-0">Kelola akun, peran, dan pembagian tim transaksi.</p></div><a class="btn btn-primary" href="<?= url('/users/create') ?>"><i class="bi bi-person-plus me-1"></i>Tambah User</a></div>
<div class="panel-card"><div class="table-responsive"><table class="table modern-table align-middle"><thead><tr><th>Nama</th><th>Username</th><th>Email</th><th>Role</th><th>Tim</th><th>Status</th><th>Login Terakhir</th><th class="text-end">Aksi</th></tr></thead><tbody><?php foreach($users as$u):?><tr><td><div class="d-flex align-items-center gap-2"><div class="avatar-sm"><?= e(strtoupper(substr($u['name'],0,1))) ?></div><strong><?= e($u['name']) ?></strong></div></td><td><?= e($u['username']) ?></td><td><?= e($u['email']) ?></td><td><span class="code-pill"><?= e($u['role_name']) ?></span></td><td><?= $u['transaction_team']?'Tim '.e($u['transaction_team']):'-' ?></td><td><?= status_badge($u['is_active']?'active':'inactive') ?></td><td><?= format_datetime($u['last_login_at']) ?></td><td class="text-end"><a class="btn btn-sm btn-light" href="<?= url('/users/'.$u['id'].'/edit') ?>"><i class="bi bi-pencil"></i></a><?php if((int)$u['id']!==(int)auth_user()['id']):?><form method="post" class="d-inline" action="<?= url('/users/'.$u['id']) ?>" data-confirm="Hapus user ini?"><?= csrf_field().method_field('DELETE') ?><button class="btn btn-sm btn-light text-danger"><i class="bi bi-trash"></i></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
